#!/usr/bin/env bash
# Builds docs/decisions/README.md from the title, status, and feature (or older design) line of each decision record.
# With --check, fails when the index is out of date instead of writing it.
set -euo pipefail
shopt -s nullglob
cd "$(dirname "${BASH_SOURCE[0]}")/../.."

readonly decisions_dir="docs/decisions"
readonly index_file="$decisions_dir/README.md"
readonly no_design="Project-wide"

fail() {
    echo "::error::$1" >&2
    exit 1
}

field() {
    sed -n "s/^- \*\*$2:\*\* //p" "$1" | head -n 1
}

build_index() {
    local -A groups=()
    local -a group_order=()
    local superseded=""

    for record in "$decisions_dir"/[0-9][0-9][0-9][0-9]-*.md; do
        local file title status group entry
        file="$(basename "$record")"
        title="$(head -n 1 "$record" | sed -n 's/^# \([0-9][0-9]*\. .*\)$/\1/p')"
        status="$(field "$record" Status)"
        group="$(field "$record" Feature)"
        [[ -n "$group" ]] || group="$(field "$record" Design)"
        [[ -n "$title" ]] || fail "$record must start with '# N. Title'."
        [[ -n "$status" ]] || fail "$record has no '- **Status:**' line."

        entry="- [$title]($file)"
        if [[ "$status" == Superseded* ]]; then
            superseded+="$entry: ${status,}"$'\n'
            continue
        fi
        [[ "$status" == "Accepted" ]] || entry+=" (${status#Accepted, })"
        group="${group:-$no_design}"
        [[ -v "groups[$group]" ]] || group_order+=("$group")
        groups[$group]+="$entry"$'\n'
    done

    print_header
    for group in "${group_order[@]}"; do
        printf '\n## %s\n\n%s' "$(capitalize_link_text "$group")" "${groups[$group]}"
    done
    if [[ -n "$superseded" ]]; then
        printf '\n## Superseded\n\n%s' "$superseded"
    fi
}

capitalize_link_text() {
    if [[ "$1" != \[* ]]; then
        echo "$1"
        return
    fi
    local rest="${1:1}"
    echo "[${rest^}"
}

print_header() {
    cat <<'EOF'
# Decision records

<!-- Generated by .github/scripts/build-decision-index.sh. Do not edit by hand. -->

One line per record, grouped by the feature that made it. Before changing something a record may cover, find it
here and open only that record. [`docs/README.md`](../README.md) says which choices get a record.
EOF
}

index="$(build_index)"
if [[ "${1:-}" == "--check" ]]; then
    diff -u "$index_file" <(printf '%s\n' "$index") ||
        fail "$index_file is out of date. Run .github/scripts/build-decision-index.sh and commit the result."
else
    printf '%s\n' "$index" > "$index_file"
fi
